"""DS4_EXPERT_UNION=1: measure how many DISTINCT experts a decode step touches.

The decode roof (docs/DS4_DECODE_CEILING.md) is dominated by routed-expert
bytes, and those scale with the *union* of experts the step's positions select,
not with 6-per-token. Independent routing would put the union at ~34 experts per
layer for a K=6 verify; perfectly correlated routing puts it at 6. That factor
of ~5.7 moves the physics ceiling by 60%, and nothing static can settle it --
it has to be measured against real traffic.

This wraps `make_routing_data` in vLLM's matmul_ogs MoE path, which is the one
choke point where `topk_ids` exists for both the legacy-`routing_from_bitmatrix`
and the `SparseMatrix` branch. It is NOT reachable through vLLM's own
`--enable-return-routed-experts`: that capturer hangs off `BaseRouter.route()`,
which this model never calls (routing happens inside the triton_kernels path).

Per call it records (n_rows, n_distinct, n_local_experts) into a preallocated
device buffer using only elementwise kernels -- no D2H copy, no sync, so it does
not serialise the step it is measuring. The buffer is copied out once when the
window closes.

Cost: ~4 extra small kernel launches per MoE call, ~184 per step against the
~5,230 the step already issues (~3.5%). Off unless DS4_EXPERT_UNION=1.

Env:
    DS4_EXPERT_UNION=1        enable
    DS4_EU_START=200          skip this many calls first (warmup + prefill)
    DS4_EU_CALLS=2000         window size in MoE calls (~46/decode step)
    DS4_EU_OUT=~/vllm-prof            output directory

Analyse the dump with host/bench/expert_union.py.
"""

import atexit
import os

import torch

_ENABLED = os.environ.get("DS4_EXPERT_UNION") == "1"
_START = int(os.environ.get("DS4_EU_START", "200"))
_CALLS = int(os.environ.get("DS4_EU_CALLS", "2000"))
_OUT = os.path.expanduser(os.environ.get("DS4_EU_OUT", "~/vllm-prof"))

_buf = None          # [_CALLS, 3] int32 on device
_n = 0               # calls seen
_done = False
_installed = False


def _record(topk_ids, num_local_experts):
    """Accumulate one routing call. Device-only; never synchronises."""
    global _buf, _n, _done
    if _done:
        return
    _n += 1
    if _n <= _START:
        return
    i = _n - _START - 1
    if i >= _CALLS:
        _flush()
        return

    ids = topk_ids.reshape(-1).long()
    if _buf is None:
        _buf = torch.zeros(_CALLS, 3, dtype=torch.int32, device=ids.device)

    # Slot 0 absorbs the -1 padding rows so no boolean mask (and therefore no
    # size-dependent sync) is needed; real experts land at 1..num_local.
    seen = torch.zeros(num_local_experts + 1, dtype=torch.bool, device=ids.device)
    seen[ids + 1] = True

    _buf[i, 0] = topk_ids.shape[0]
    _buf[i, 1] = seen[1:].sum()
    _buf[i, 2] = num_local_experts


def _flush():
    """Copy the buffer out once and write the dump."""
    global _done
    if _done or _buf is None:
        return
    _done = True
    try:
        rows = _buf.cpu().tolist()
        os.makedirs(_OUT, exist_ok=True)
        path = os.path.join(_OUT, f"expert_union_{os.getpid()}.tsv")
        with open(path, "w") as fh:
            fh.write("# n_rows\tn_distinct\tn_local_experts\n")
            for n_rows, n_distinct, n_local in rows:
                if n_rows:
                    fh.write(f"{n_rows}\t{n_distinct}\t{n_local}\n")
        print(f"[ds4_expert_union] wrote {path}", flush=True)
    except Exception as exc:  # a probe must never take the engine down
        print(f"[ds4_expert_union] flush failed: {exc}", flush=True)


def install():
    """Idempotently wrap make_routing_data. Safe to call more than once."""
    global _installed
    if not _ENABLED or _installed:
        return
    try:
        from vllm.model_executor.layers.fused_moe.experts import (
            gpt_oss_triton_kernels_moe as m,
        )
    except Exception as exc:
        print(f"[ds4_expert_union] not installed: {exc}", flush=True)
        return

    orig = m.make_routing_data

    def wrapped(topk_ids, topk_weights, num_local_experts, *a, **kw):
        try:
            _record(topk_ids, num_local_experts)
        except Exception:
            pass  # never let the probe break routing
        return orig(topk_ids, topk_weights, num_local_experts, *a, **kw)

    wrapped._ds4_orig = orig
    m.make_routing_data = wrapped
    _installed = True
    # Also flush on shutdown, so a run that ends before the window fills still
    # leaves a (shorter) usable dump rather than nothing.
    atexit.register(_flush)
    print(
        f"[ds4_expert_union] installed: skip {_START} calls, window {_CALLS}, "
        f"out {_OUT}",
        flush=True,
    )
